import{_ as o,o as e,c as r,a2 as a}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"访问控制","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/access.md","filePath":"zh/guides/access.md","lastUpdated":1790952322000}'),l={name:"zh/guides/access.md"};function d(n,t,i,s,h,c){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="访问控制" tabindex="-1">访问控制 <a class="header-anchor" href="#访问控制" aria-label="Permalink to &quot;访问控制&quot;">​</a></h1><p>Memoh 的访问控制分成两层：</p><ul><li><strong>渠道成员</strong>：控制来自 Telegram、Discord、飞书、QQ 等 IM 渠道的身份。</li><li><strong>工作区成员</strong>：控制客户端和工作区里的 Memoh 注册用户。</li></ul><p>旧的 ACL 规则模型仍然存在，但现在主要作为渠道聊天权限背后的高级引擎。日常配置应优先从 Bot 的 <strong>Access</strong> 页开始，使用 <strong>渠道成员</strong> 和 <strong>工作区成员</strong> 两个入口。</p><hr><h2 id="核心模型" tabindex="-1">核心模型 <a class="header-anchor" href="#核心模型" aria-label="Permalink to &quot;核心模型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>身份</th><th>控制内容</th></tr></thead><tbody><tr><td><strong>渠道成员</strong></td><td>IM 平台上观测到的渠道身份</td><td>这个平台身份能否和 Bot 聊天，以及能否通过 IM 命令管理 Bot</td></tr><tr><td><strong>工作区成员</strong></td><td>Memoh 注册用户账号</td><td>这个用户能否在客户端使用 Bot、读写文件、执行工作区命令或管理 Bot 设置</td></tr></tbody></table><p>这两层可以通过账号绑定连接起来。工作区用户可在 <strong>Profile -&gt; Connected Accounts</strong> 生成一次性代码，然后在 IM 里向某个 Memoh Bot 发送 <code>/link &lt;code&gt;</code>，把发送消息的渠道身份绑定到自己的 Memoh 账号。</p><p>绑定本身不授予访问权限。它只负责连接身份。真正的权限仍来自渠道成员、工作区成员、Bot 所有者或系统管理员身份。</p><hr><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><h3 id="允许任何-im-用户聊天" tabindex="-1">允许任何 IM 用户聊天 <a class="header-anchor" href="#允许任何-im-用户聊天" aria-label="Permalink to &quot;允许任何 IM 用户聊天&quot;">​</a></h3><ol><li>打开 Bot 的 <strong>Access</strong> 页。</li><li>进入 <strong>渠道成员</strong>。</li><li>将 <strong>访问模式</strong> 设为 <strong>黑名单模式</strong>。</li><li>保持成员列表为空，或只添加要拦截的身份。</li></ol><p>黑名单模式表示 ACL 默认行为是 <code>allow</code>。除非命中拒绝规则，否则所有人都能聊天。</p><h3 id="只允许指定-im-身份" tabindex="-1">只允许指定 IM 身份 <a class="header-anchor" href="#只允许指定-im-身份" aria-label="Permalink to &quot;只允许指定 IM 身份&quot;">​</a></h3><ol><li>打开 <strong>渠道成员</strong>。</li><li>将 <strong>访问模式</strong> 设为 <strong>白名单模式</strong>。</li><li>添加允许访问的渠道身份。</li><li>为每个允许身份保持 <strong>聊天</strong> 勾选。</li></ol><p>白名单模式表示 ACL 默认行为是 <code>deny</code>。只有命中允许规则的身份能聊天。</p><h3 id="给-web-用户授权" tabindex="-1">给 Web 用户授权 <a class="header-anchor" href="#给-web-用户授权" aria-label="Permalink to &quot;给 Web 用户授权&quot;">​</a></h3><ol><li>打开 <strong>工作区成员</strong>。</li><li>添加指定成员，或添加 <strong>全部成员</strong>。</li><li>选择该成员应该拥有的权限。</li></ol><p>工作区访问面向 Memoh 注册用户。除非用户绑定了自己的 IM 身份，否则它和 IM 聊天权限是分开的。</p><hr><h2 id="渠道成员" tabindex="-1">渠道成员 <a class="header-anchor" href="#渠道成员" aria-label="Permalink to &quot;渠道成员&quot;">​</a></h2><p>渠道成员是 IM 侧的访问控制入口。</p><p>每一行代表一个<strong>渠道身份</strong>（一个 Telegram 用户或 Discord 成员），或一个<strong>群聊</strong>（见下）。成员从卡片头部的内联选择器添加，个人身份和群聊候选在同一个下拉里分区展示。每一行有两个互相独立的权限：</p><table tabindex="0"><thead><tr><th>权限</th><th>含义</th></tr></thead><tbody><tr><td><strong>聊天</strong></td><td>控制该 IM 身份发来的入站消息能否触发 Bot。</td></tr><tr><td><strong>管理</strong></td><td>控制该身份能否通过 IM slash command 管理 Bot。管理权限不会自动授予聊天权限。</td></tr></tbody></table><h3 id="聊天" tabindex="-1">聊天 <a class="header-anchor" href="#聊天" aria-label="Permalink to &quot;聊天&quot;">​</a></h3><p>聊天勾选框背后是 <code>chat.trigger</code> 的 ACL 规则。</p><p>在<strong>黑名单模式</strong>下：</p><ul><li>默认是 <code>allow</code></li><li>添加身份或取消勾选聊天，会创建拒绝规则</li><li>勾选聊天，会删除该身份的拒绝规则</li></ul><p>在<strong>白名单模式</strong>下：</p><ul><li>默认是 <code>deny</code></li><li>添加身份或勾选聊天，会创建允许规则</li><li>取消勾选聊天，会删除该身份的允许规则</li></ul><h3 id="管理" tabindex="-1">管理 <a class="header-anchor" href="#管理" aria-label="Permalink to &quot;管理&quot;">​</a></h3><p>管理勾选框会为该渠道身份写入一个本地 Channel Access 覆盖。</p><p>管理权限用于 IM 命令。它让某个渠道身份可以在 owner 级别的 slash command 流程里作为 Bot 管理者行动。它刻意和聊天权限分开：即使某个身份有管理权限，只要聊天关闭或 ACL 拒绝，它的普通聊天消息仍会被拦截。</p><h3 id="群聊作为成员" tabindex="-1">群聊作为成员 <a class="header-anchor" href="#群聊作为成员" aria-label="Permalink to &quot;群聊作为成员&quot;">​</a></h3><p>除了单个身份，也可以把整个<strong>群聊</strong>加成一行成员。群聊候选来自 Bot 在各渠道观测到的会话，行上带&quot;群&quot;标记。</p><ul><li>群行的<strong>聊天</strong>勾选含义是&quot;这个群里的所有人&quot;——白名单模式下放行全群，黑名单模式下屏蔽全群。</li><li><strong>群没有管理权限</strong>。管理者永远是单个渠道身份。</li><li>要表达&quot;这个人、在这个群里&quot;这类组合，仍然走高级 ACL 规则。</li></ul><h3 id="平台成员" tabindex="-1">平台成员 <a class="header-anchor" href="#平台成员" aria-label="Permalink to &quot;平台成员&quot;">​</a></h3><p>如果某个渠道身份已经绑定到此 Bot 的工作区成员，这一行会被标记为平台成员。</p><p>当对应的工作区成员在 <strong>工作区成员</strong> 中拥有 <strong>管理</strong> 权限时，该渠道身份会自动继承管理权限。渠道成员行会显示这个管理权限来自继承。若你在渠道成员里切换管理权限，Memoh 会写入本地覆盖：</p><ul><li>本地<strong>开启</strong>会强制该渠道身份拥有管理权限</li><li>本地<strong>关闭</strong>会压制该渠道身份继承来的管理权限</li><li><strong>恢复继承</strong>会删除本地覆盖，重新跟随工作区成员权限</li></ul><p>只有纯本地渠道行可以从渠道成员里删除。平台成员行来自账号绑定，应通过权限设置或断开绑定来管理。</p><hr><h2 id="工作区成员" tabindex="-1">工作区成员 <a class="header-anchor" href="#工作区成员" aria-label="Permalink to &quot;工作区成员&quot;">​</a></h2><p>工作区成员是 Web/工作区侧的访问控制入口。</p><p>你可以授权给：</p><ul><li><strong>指定成员</strong></li><li><strong>全部成员</strong></li></ul><p>Bot 所有者会作为隐式 owner 条目显示，并始终拥有完整权限。系统管理员也会解析为完整权限。</p><p>工作区权限包括：</p><table tabindex="0"><thead><tr><th>权限</th><th>允许的操作</th></tr></thead><tbody><tr><td><strong>可对话</strong></td><td>在 Web 聊天界面使用 Bot。</td></tr><tr><td><strong>可读文件</strong></td><td>读取 Bot 工作区文件。</td></tr><tr><td><strong>可写文件</strong></td><td>修改 Bot 工作区文件，并隐含可读文件。</td></tr><tr><td><strong>可执行命令</strong></td><td>运行工作区执行流程。</td></tr><tr><td><strong>可管理</strong></td><td>管理 Bot 设置和访问控制，并隐含所有其他工作区权限。</td></tr></tbody></table><p>工作区管理权限也会流入渠道成员。若一个拥有工作区管理权限的用户绑定了 Telegram 身份，该 Telegram 身份会在渠道侧继承管理权限。</p><p>工作区的<strong>可对话</strong>不等于渠道的<strong>聊天</strong>。工作区权限授权客户端与工作区 API；渠道聊天权限则通过 ACL 引擎授权 IM 入站消息。</p><hr><h2 id="绑定渠道身份" tabindex="-1">绑定渠道身份 <a class="header-anchor" href="#绑定渠道身份" aria-label="Permalink to &quot;绑定渠道身份&quot;">​</a></h2><p>用户可在 <strong>Profile -&gt; Connected Accounts</strong> 绑定 IM 身份：</p><ol><li>点击 <strong>Connect</strong>。</li><li>复制生成的 <code>/link &lt;code&gt;</code> 命令。</li><li>在 IM 渠道里把它发送给某个 Memoh Bot。</li><li>该代码会把发送消息的渠道身份绑定到当前 Memoh 用户账号。</li></ol><p>重要细节：</p><ul><li>link code 是一次性的，并且会在短时间后过期</li><li>即使发送者被聊天 ACL 拒绝，<code>/link &lt;code&gt;</code> 仍然允许执行，所以用户能从未绑定状态恢复</li><li>绑定是账号级别的：它全局连接工作区用户和渠道身份</li><li>绑定本身不授予聊天或管理权限</li></ul><p>绑定完成后，对应渠道成员行可以继承工作区管理权限。</p><hr><h2 id="访问模式与高级-acl-规则" tabindex="-1">访问模式与高级 ACL 规则 <a class="header-anchor" href="#访问模式与高级-acl-规则" aria-label="Permalink to &quot;访问模式与高级 ACL 规则&quot;">​</a></h2><p>渠道聊天使用 ACL 引擎。Access 页把它呈现为<strong>访问模式</strong>加可选的高级规则。</p><table tabindex="0"><thead><tr><th>访问模式</th><th>ACL 默认行为</th><th>真正影响结果的规则</th></tr></thead><tbody><tr><td><strong>黑名单模式</strong></td><td><code>allow</code></td><td><code>deny</code> 规则</td></tr><tr><td><strong>白名单模式</strong></td><td><code>deny</code></td><td><code>allow</code> 规则</td></tr></tbody></table><p>只有和当前默认行为相反的规则会覆盖默认模式。和默认行为相同的规则不会改变结果。</p><p>高级规则可以针对：</p><ul><li>所有用户</li><li>某个平台上的所有用户</li><li>某个渠道身份</li><li>某个平台上的某个渠道身份</li></ul><p>高级规则也可以限定在：</p><ul><li>任意聊天</li><li>私聊</li><li>群聊</li><li>话题/线程</li><li>指定会话 ID</li><li>指定 thread ID</li></ul><p>规则目标负责平台过滤。来源范围负责会话和 thread 过滤。</p><p>和旧 ACL 文档不同，当前版本不再提供手动规则优先级或拖拽排序行为。理解时应按“当前默认模式 + 命中的反向规则”来判断。</p><hr><h2 id="创建预设" tabindex="-1">创建预设 <a class="header-anchor" href="#创建预设" aria-label="Permalink to &quot;创建预设&quot;">​</a></h2><p>创建 Bot 时选择的 ACL 预设，只初始化渠道聊天行为。之后可在 <strong>渠道成员</strong> 中修改。</p><table tabindex="0"><thead><tr><th>预设</th><th>初始行为</th></tr></thead><tbody><tr><td><code>allow_all</code></td><td>默认行为 <code>allow</code>；不额外创建规则</td></tr><tr><td><code>private_only</code></td><td>默认行为 <code>deny</code>；允许私聊</td></tr><tr><td><code>group_only</code></td><td>默认行为 <code>deny</code>；允许群聊</td></tr><tr><td><code>group_and_thread_only</code></td><td>默认行为 <code>deny</code>；允许群聊和 thread</td></tr><tr><td><code>deny_all</code></td><td>默认行为 <code>deny</code>；不额外创建允许规则</td></tr></tbody></table><p>预设不会配置工作区成员，也不会创建账号绑定。</p><hr><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="公开-im-bot-只拉黑少数人" tabindex="-1">公开 IM Bot，只拉黑少数人 <a class="header-anchor" href="#公开-im-bot-只拉黑少数人" aria-label="Permalink to &quot;公开 IM Bot，只拉黑少数人&quot;">​</a></h3><p>在渠道成员中使用<strong>黑名单模式</strong>。默认保持聊天开启，只添加被拦截的身份。只有需要拦截整个平台或某个群/thread 上下文时，才使用高级规则。</p><h3 id="私有-im-bot" tabindex="-1">私有 IM Bot <a class="header-anchor" href="#私有-im-bot" aria-label="Permalink to &quot;私有 IM Bot&quot;">​</a></h3><p>在渠道成员中使用<strong>白名单模式</strong>。添加允许的渠道身份，并保持聊天勾选。如果同一批人还需要通过 IM 管理 Bot，再授予管理权限。</p><h3 id="web-团队-bot" tabindex="-1">Web 团队 Bot <a class="header-anchor" href="#web-团队-bot" aria-label="Permalink to &quot;Web 团队 Bot&quot;">​</a></h3><p>使用<strong>工作区成员</strong>。添加指定用户或全部成员，然后按 Web/工作区角色选择可对话、文件权限、命令执行和管理权限。</p><h3 id="工作区管理员同时从-telegram-管理" tabindex="-1">工作区管理员同时从 Telegram 管理 <a class="header-anchor" href="#工作区管理员同时从-telegram-管理" aria-label="Permalink to &quot;工作区管理员同时从 Telegram 管理&quot;">​</a></h3><p>在工作区成员中给该用户授予<strong>可管理</strong>。让用户用 <code>/link &lt;code&gt;</code> 绑定 Telegram 账号。其 Telegram 身份会在渠道成员中继承管理权限。如果只想禁用该身份的 Telegram 侧管理能力，可在渠道成员中关闭管理权限，创建本地覆盖。</p><hr><h2 id="排查" tabindex="-1">排查 <a class="header-anchor" href="#排查" aria-label="Permalink to &quot;排查&quot;">​</a></h2><p>访问结果不符合预期时，按顺序检查：</p><ol><li><strong>涉及哪一层？</strong> IM 消息走渠道聊天 ACL；客户端和工作区 API 走工作区成员。</li><li><strong>身份是否已绑定？</strong> Connected Accounts 决定工作区管理权限能否继承到渠道成员。</li><li><strong>当前渠道访问模式是什么？</strong> 黑名单模式默认允许；白名单模式默认拒绝。</li><li><strong>管理权限是继承还是覆盖？</strong> 渠道成员的信息弹窗会显示管理权限是跟随工作区，还是已被本地覆盖。</li><li><strong><code>/access</code> 显示什么？</strong> 在 IM 中，<code>/access</code> 会展示当前身份、写权限和发送者的聊天 ACL 上下文。</li></ol><p>请记住，管理和聊天是分开的。管理权限可以允许 owner 级别的 IM 命令，但普通入站聊天仍需要渠道聊天权限放行发送者。</p>',90)])])}const b=o(l,[["render",d]]);export{p as __pageData,b as default};
